"""
WhisperX-style CTC forced alignment (wav2vec2) for anime-whisper timing.

Uses the same Japanese default as WhisperX
(``jonatasgrosman/wav2vec2-large-xlsr-53-japanese``) via transformers —
no full ``whisperx`` package (avoids torch/CUDA stack conflicts in the
embeddable runtime). Segments need a usable [start, end] window; collapsed
anime-whisper timestamps must be expanded before calling align.
"""

from __future__ import annotations

import logging
import re
from typing import Any

import numpy as np

_log = logging.getLogger("transub_engine.asr.wav2vec_align")

SAMPLE_RATE = 16000
JA_ALIGN_MODEL_ID = "jonatasgrosman/wav2vec2-large-xlsr-53-japanese"
_ALIGN_CACHE: dict[str, Any] = {}

_SENT_END = set("。！？!?．.｡…")
_PUNCT_STRIP = re.compile(r"[\s　]+")


def wav2vec_align_available() -> bool:
    try:
        import torch  # noqa: F401
        import transformers  # noqa: F401
        import soundfile  # noqa: F401
    except Exception:
        return False
    return True


def clear_align_model_cache() -> int:
    n = len(_ALIGN_CACHE)
    _ALIGN_CACHE.clear()
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    try:
        import torch

        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass
    return n


def _load_audio_mono_16k(
    path: str,
    *,
    max_media_s: float | None = None,
) -> np.ndarray:
    """
    Load mono float32 @ 16 kHz. WAV/FLAC prefer soundfile; video containers
    (mp4/mkv/…) go through ffmpeg — same rule as TEN VAD.
    """
    from pathlib import Path as _Path

    from ..vad.ten_vad_seg import _SOUNDFILE_EXTS, _load_mono_16k_ffmpeg

    ext = _Path(path).suffix.lower()
    prefer_sf = ext in _SOUNDFILE_EXTS
    errors: list[str] = []

    if prefer_sf:
        try:
            import soundfile as sf

            audio, sr = sf.read(path, always_2d=False)
            if getattr(audio, "ndim", 1) > 1:
                audio = np.mean(audio, axis=-1)
            audio = np.asarray(audio, dtype=np.float32)
            if int(sr) != SAMPLE_RATE:
                try:
                    import librosa

                    audio = librosa.resample(
                        audio, orig_sr=int(sr), target_sr=SAMPLE_RATE
                    )
                except Exception:
                    duration = len(audio) / float(sr) if sr else 0.0
                    n = max(1, int(round(duration * SAMPLE_RATE)))
                    x_old = np.linspace(0.0, 1.0, num=len(audio), endpoint=False)
                    x_new = np.linspace(0.0, 1.0, num=n, endpoint=False)
                    audio = np.interp(x_new, x_old, audio).astype(np.float32)
            if max_media_s is not None and max_media_s > 0:
                audio = audio[: int(float(max_media_s) * SAMPLE_RATE)]
            return audio
        except Exception as err:
            errors.append(f"soundfile: {err}")
            _log.info("wav2vec soundfile failed for %s (%s); trying ffmpeg", path, err)

    try:
        return _load_mono_16k_ffmpeg(path, max_media_s=max_media_s)
    except Exception as err:
        errors.append(f"ffmpeg: {err}")

    if not prefer_sf:
        try:
            import soundfile as sf

            audio, sr = sf.read(path, always_2d=False)
            if getattr(audio, "ndim", 1) > 1:
                audio = np.mean(audio, axis=-1)
            audio = np.asarray(audio, dtype=np.float32)
            if int(sr) != SAMPLE_RATE:
                import librosa

                audio = librosa.resample(audio, orig_sr=int(sr), target_sr=SAMPLE_RATE)
            if max_media_s is not None and max_media_s > 0:
                audio = audio[: int(float(max_media_s) * SAMPLE_RATE)]
            return audio
        except Exception as err:
            errors.append(f"soundfile: {err}")

    raise RuntimeError(
        "wav2vec align could not decode audio from "
        f"{path!r} ({'; '.join(errors) or 'no decoder'})"
    )


def _get_align_model(device: str = "cpu") -> tuple[Any, dict[str, Any]]:
    key = f"{JA_ALIGN_MODEL_ID}|{device}"
    cached = _ALIGN_CACHE.get(key)
    if cached is not None:
        return cached
    import torch
    from transformers import Wav2Vec2ForCTC, Wav2Vec2Processor

    # Prefer local cache; avoid unexpected hub downloads in offline runtimes.
    load_kw: dict[str, Any] = {}
    try:
        load_kw["local_files_only"] = True
        processor = Wav2Vec2Processor.from_pretrained(JA_ALIGN_MODEL_ID, **load_kw)
        model = Wav2Vec2ForCTC.from_pretrained(JA_ALIGN_MODEL_ID, **load_kw)
    except Exception:
        load_kw.pop("local_files_only", None)
        processor = Wav2Vec2Processor.from_pretrained(JA_ALIGN_MODEL_ID)
        model = Wav2Vec2ForCTC.from_pretrained(JA_ALIGN_MODEL_ID)
    model = model.to(device)
    model.eval()
    labels = processor.tokenizer.get_vocab()
    dictionary = {str(ch).lower(): int(code) for ch, code in labels.items()}
    meta = {"dictionary": dictionary, "language": "ja"}
    _ALIGN_CACHE[key] = (model, processor, meta)
    return _ALIGN_CACHE[key]


def _get_trellis(emission: Any, tokens: list[int], blank_id: int = 0) -> Any:
    import torch

    num_frame = emission.size(0)
    num_tokens = len(tokens)
    trellis = torch.empty((num_frame + 1, num_tokens + 1))
    trellis[0, 0] = 0
    trellis[1:, 0] = torch.cumsum(emission[:, blank_id], 0)
    trellis[0, -num_tokens:] = -float("inf")
    trellis[-num_tokens:, 0] = float("inf")
    for t in range(num_frame):
        trellis[t + 1, 1:] = torch.maximum(
            trellis[t, 1:] + emission[t, blank_id],
            trellis[t, :-1] + emission[t, tokens],
        )
    return trellis


def _backtrack(trellis: Any, emission: Any, tokens: list[int], blank_id: int = 0):
    import torch

    j = trellis.size(1) - 1
    t_start = int(torch.argmax(trellis[:, j]).item())
    path: list[tuple[int, int, float]] = []
    for t in range(t_start, 0, -1):
        stayed = trellis[t - 1, j] + emission[t - 1, blank_id]
        changed = trellis[t - 1, j - 1] + emission[t - 1, tokens[j - 1]]
        prob = (
            emission[t - 1, tokens[j - 1] if changed > stayed else blank_id]
            .exp()
            .item()
        )
        path.append((j - 1, t - 1, float(prob)))
        if changed > stayed:
            j -= 1
            if j == 0:
                break
    else:
        return None
    return path[::-1]


def _merge_repeats(path: list[tuple[int, int, float]], transcript: str):
    segs: list[tuple[str, int, int, float]] = []
    i1 = 0
    while i1 < len(path):
        i2 = i1
        while i2 < len(path) and path[i1][0] == path[i2][0]:
            i2 += 1
        score = sum(path[k][2] for k in range(i1, i2)) / max(1, i2 - i1)
        segs.append(
            (
                transcript[path[i1][0]],
                path[i1][1],
                path[i2 - 1][1] + 1,
                score,
            )
        )
        i1 = i2
    return segs


def _align_one_window(
    *,
    waveform: np.ndarray,
    text: str,
    t0: float,
    t1: float,
    model: Any,
    processor: Any,
    dictionary: dict[str, int],
    device: str,
) -> dict[str, Any] | None:
    """Align ``text`` inside audio [t0, t1]; return refined start/end + chars."""
    import torch

    text = str(text or "").strip()
    if not text or t1 <= t0 + 0.05:
        return None
    f1 = max(0, int(t0 * SAMPLE_RATE))
    f2 = min(len(waveform), int(t1 * SAMPLE_RATE))
    if f2 - f1 < 400:
        return None
    clip = waveform[f1:f2]
    # Characters present in the align vocabulary (JA: mostly kana/kanji).
    clean_chars: list[str] = []
    clean_idx: list[int] = []
    for i, ch in enumerate(text):
        key = ch.lower()
        if key in dictionary:
            clean_chars.append(key)
            clean_idx.append(i)
        elif ch.strip():
            # Keep position with wildcard later
            clean_chars.append(key)
            clean_idx.append(i)
    if not clean_chars:
        return None
    text_clean = "".join(clean_chars)

    inputs = processor(
        clip, sampling_rate=SAMPLE_RATE, return_tensors="pt", padding=True
    )
    input_values = inputs.input_values.to(device)
    with torch.inference_mode():
        logits = model(input_values).logits
    emission = torch.log_softmax(logits, dim=-1)[0].cpu()

    blank_id = 0
    for char, code in dictionary.items():
        if char in ("[pad]", " ", "|"):
            blank_id = int(code)
            break

    has_wildcard = any(c not in dictionary for c in text_clean)
    if has_wildcard:
        non_blank = torch.ones(emission.size(1), dtype=torch.bool)
        non_blank[blank_id] = False
        wildcard_col = emission[:, non_blank].max(dim=1).values
        emission = torch.cat([emission, wildcard_col.unsqueeze(1)], dim=1)
        wild_id = emission.size(1) - 1
        tokens = [dictionary.get(c, wild_id) for c in text_clean]
    else:
        tokens = [dictionary[c] for c in text_clean]

    trellis = _get_trellis(emission, tokens, blank_id)
    path = _backtrack(trellis, emission, tokens, blank_id)
    if path is None:
        return None
    char_segs = _merge_repeats(path, text_clean)
    duration = t1 - t0
    ratio = duration * 1.0 / max(1, trellis.size(0) - 1)

    char_times: list[dict[str, Any]] = []
    for cdx, ch in enumerate(text):
        if cdx not in clean_idx:
            char_times.append({"char": ch, "start": None, "end": None})
            continue
        j = clean_idx.index(cdx)
        seg = char_segs[j]
        char_times.append(
            {
                "char": ch,
                "start": round(seg[1] * ratio + t0, 3),
                "end": round(seg[2] * ratio + t0, 3),
            }
        )

    starts = [c["start"] for c in char_times if c["start"] is not None]
    ends = [c["end"] for c in char_times if c["end"] is not None]
    if not starts or not ends:
        return None
    return {
        "start": float(min(starts)),
        "end": float(max(ends)),
        "text": text,
        "chars": char_times,
    }


def _split_aligned_chars_to_cues(
    aligned: dict[str, Any],
    *,
    meta: dict[str, Any] | None = None,
    max_chars: int = 28,
) -> list[dict[str, Any]]:
    """Split character-aligned text into subtitle-sized cues."""
    chars = aligned.get("chars") or []
    text = str(aligned.get("text") or "")
    if not chars:
        item = {
            "start": float(aligned["start"]),
            "end": float(aligned["end"]),
            "text": text,
        }
        if meta:
            item.update(meta)
        return [item]

    cues: list[dict[str, Any]] = []
    buf: list[dict[str, Any]] = []
    meta = dict(meta or {})

    def _flush() -> None:
        nonlocal buf
        if not buf:
            return
        piece = "".join(str(c.get("char") or "") for c in buf).strip()
        if not piece:
            buf = []
            return
        starts = [c["start"] for c in buf if c.get("start") is not None]
        ends = [c["end"] for c in buf if c.get("end") is not None]
        if not starts or not ends:
            buf = []
            return
        item = {
            "start": float(min(starts)),
            "end": max(float(max(ends)), float(min(starts)) + 0.2),
            "text": piece,
            **meta,
        }
        cues.append(item)
        buf = []

    for ch in chars:
        buf.append(ch)
        raw = str(ch.get("char") or "")
        joined = "".join(str(c.get("char") or "") for c in buf)
        disp = len(_PUNCT_STRIP.sub("", joined))
        if raw in _SENT_END and disp >= 1:
            _flush()
        elif disp >= max_chars:
            _flush()
    _flush()
    return cues or [
        {
            "start": float(aligned["start"]),
            "end": float(aligned["end"]),
            "text": text,
            **meta,
        }
    ]


def expand_segments_for_align(
    cues: list[dict[str, Any]] | None,
    *,
    media_end_s: float | None = None,
    min_window_s: float = 2.0,
    default_span_s: float = 30.0,
) -> list[dict[str, Any]]:
    """
    Ensure each cue has a wide enough [start, end] for wav2vec2 windows.

    anime-whisper collapsed timestamps (end≈start) are expanded to the next
    cue start or ``default_span_s``.
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    out: list[dict[str, Any]] = []
    n = len(ordered)
    for i, cue in enumerate(ordered):
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        if end - start < min_window_s:
            if i + 1 < n:
                boundary = float(ordered[i + 1].get("start") or start)
            elif media_end_s is not None and float(media_end_s) > start:
                boundary = float(media_end_s)
            else:
                boundary = start + default_span_s
            end = max(start + min_window_s, min(boundary, start + default_span_s))
        item = dict(cue)
        item["start"] = start
        item["end"] = end
        out.append(item)
    return out


def merge_cues_into_decode_windows(
    cues: list[dict[str, Any]] | None,
    *,
    span_s: float = 30.0,
    media_end_s: float | None = None,
) -> list[dict[str, Any]]:
    """
    Re-pack rate-split anime cues into ~30s decode windows for forced align.

    anime-whisper emits one text blob per ~30s step; after CPS repair those
    blobs are split into short touching cues whose windows are too narrow for
    wav2vec2. Merging by floor(start/span) restores a wide enough search range.
    """
    if not cues:
        return []
    span = max(5.0, float(span_s))
    buckets: dict[int, list[dict[str, Any]]] = {}
    for cue in cues:
        if not isinstance(cue, dict):
            continue
        text = str(cue.get("text") or "").strip()
        if not text:
            continue
        start = float(cue.get("start") or 0)
        key = int(max(0.0, start) // span)
        buckets.setdefault(key, []).append(dict(cue))
    out: list[dict[str, Any]] = []
    for key in sorted(buckets):
        parts = sorted(
            buckets[key],
            key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
        )
        text = "".join(str(p.get("text") or "").strip() for p in parts)
        if not text:
            continue
        start = key * span
        end = start + span
        if media_end_s is not None:
            end = min(end, float(media_end_s))
        # Carry confidence meta from the first part when present.
        meta = {
            k: v
            for k, v in parts[0].items()
            if k not in ("start", "end", "text", "words", "chars")
        }
        item = {**meta, "start": start, "end": max(end, start + 1.0), "text": text}
        out.append(item)
    return out


def _align_looks_collapsed(
    cues: list[dict[str, Any]],
    *,
    media_end_s: float,
) -> bool:
    """True when forced-align timestamps are still anime-whisper-style blobs."""
    if not cues:
        return True
    spoken = 0.0
    chars = 0
    for c in cues:
        text = str(c.get("text") or "")
        chars += len(re.sub(r"\s+", "", text))
        spoken += max(0.0, float(c.get("end") or 0) - float(c.get("start") or 0))
    if chars < 12:
        return False
    # Healthy JA speech is roughly 6–14 chars/s; >>40 cps ⇒ failed CTC path.
    cps = chars / max(spoken, 1e-3)
    if cps > 40.0:
        return True
    # Almost no timeline coverage relative to media / text volume.
    if media_end_s > 1.0 and spoken < min(media_end_s * 0.05, chars / 25.0):
        return True
    return False


def align_cues_wav2vec2(
    cues: list[dict[str, Any]] | None,
    *,
    media_path: str,
    device: str = "cpu",
    media_end_s: float | None = None,
) -> list[dict[str, Any]] | None:
    """
    Forced-align cue texts onto ``media_path`` with Japanese wav2vec2.

    Returns refined cues, or ``None`` if alignment is unavailable / fails entirely
    (caller should fall back to ja-1.5b timing). Soft-AV / breathy speech often
    collapses CTC paths — those results are rejected so ASR timing can take over.
    """
    if not cues or not wav2vec_align_available():
        return None
    try:
        import torch

        # Prefer CUDA only when this torch build actually has it.
        want = str(device or "cpu").strip().lower()
        if want in ("cuda", "auto") and torch.cuda.is_available():
            dev = "cuda"
        else:
            dev = "cpu"
        end_hint = (
            float(media_end_s)
            if media_end_s is not None and float(media_end_s) > 0
            else None
        )
        waveform = _load_audio_mono_16k(media_path, max_media_s=end_hint)
        audio_dur = len(waveform) / float(SAMPLE_RATE)
        end_cap = float(media_end_s) if media_end_s is not None else audio_dur
        end_cap = min(end_cap, audio_dur)
        # Prefer 30s decode windows (anime-whisper native step) so wav2vec2
        # can search the whole chunk — not the narrow rate-split subcues.
        windows = merge_cues_into_decode_windows(
            cues, span_s=30.0, media_end_s=end_cap
        )
        if not windows:
            windows = expand_segments_for_align(cues, media_end_s=end_cap)
        if not windows:
            return None
        model, processor, meta = _get_align_model(dev)
        dictionary = meta["dictionary"]
        out: list[dict[str, Any]] = []
        for i, cue in enumerate(windows):
            pass_meta = {
                k: v
                for k, v in cue.items()
                if k not in ("start", "end", "text", "words", "chars")
            }
            aligned = _align_one_window(
                waveform=waveform,
                text=str(cue.get("text") or ""),
                t0=float(cue.get("start") or 0),
                t1=min(float(cue.get("end") or 0), end_cap),
                model=model,
                processor=processor,
                dictionary=dictionary,
                device=dev,
            )
            if aligned is None:
                item = dict(cue)
                item.pop("words", None)
                out.append(item)
            else:
                out.extend(
                    _split_aligned_chars_to_cues(aligned, meta=pass_meta, max_chars=28)
                )
            # Early abort: first window already collapsed ⇒ skip remaining cost.
            if i == 0 and _align_looks_collapsed(out, media_end_s=max(end_cap, 1.0)):
                _log.warning(
                    "wav2vec2 align collapsed on first window (soft-AV / weak JA match); "
                    "falling back to ASR timing"
                )
                return None
        if _align_looks_collapsed(out, media_end_s=max(end_cap, 1.0)):
            _log.warning("wav2vec2 align collapsed; falling back to ASR timing")
            return None
        for i, item in enumerate(out):
            text = str(item.get("text") or "")
            n = max(len(re.sub(r"\s+", "", text)), 1)
            min_dur = max(0.35, min(6.5, n / 20.0))
            start = float(item.get("start") or 0)
            end = float(item.get("end") or start)
            if end - start >= min_dur - 1e-6:
                continue
            limit = start + 6.5
            if i + 1 < len(out):
                limit = min(limit, float(out[i + 1].get("start") or limit) - 0.05)
            item["end"] = max(end, min(start + min_dur, limit))
            if float(item["end"]) <= start:
                item["end"] = start + 0.35
        return out
    except Exception as err:
        _log.warning("wav2vec2 align failed: %s", err)
        return None
